pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const PDF_URL="asset/ar-bjbs-2025.pdf";let pdfDoc=null;let pageFlip=null;let zoomLevel=1;const cache=new Map();const PAGE_WIDTH=800;const PAGE_HEIGHT=1130;let thicknessLocked=!1;const leftThickness=document.getElementById("leftThickness");const rightThickness=document.getElementById("rightThickness");function createPlaceholder(pageNum){const div=document.createElement("div");div.className="page";div.dataset.page=pageNum;div.innerHTML=`
        <div class="page-loader">
            <div class="spinner"></div>
        </div>
    `;return div}
function positionButtons(){const bookEl=document.getElementById("book");const prevBtn=document.querySelector(".nav-prev");const nextBtn=document.querySelector(".nav-next");if(!bookEl||!prevBtn||!nextBtn)return;const rect=bookEl.getBoundingClientRect();const leftPos=Math.max(20,rect.left-70);const rightPos=Math.min(window.innerWidth-70,rect.right+20);prevBtn.style.left=`${leftPos}px`;nextBtn.style.left=`${rightPos}px`}
function updateThickness(){if(!leftThickness||!rightThickness)return;if(window.innerWidth<768){leftThickness.style.opacity="0";rightThickness.style.opacity="0";return}
if(thicknessLocked||!pdfDoc||!pageFlip)return;const items=[...document.querySelectorAll(".stf__item")].filter((el)=>{const rect=el.getBoundingClientRect();return rect.width>50&&rect.height>50});if(!items.length)return;const rects=items.map((el)=>el.getBoundingClientRect());const minLeft=Math.min(...rects.map((r)=>r.left));const maxRight=Math.max(...rects.map((r)=>r.right));const minTop=Math.min(...rects.map((r)=>r.top));const maxBottom=Math.max(...rects.map((r)=>r.bottom));const height=maxBottom-minTop;const currentIndex=pageFlip.getCurrentPageIndex();if(currentIndex===0){leftThickness.style.opacity="0";rightThickness.style.opacity="0";return}
const ratio=currentIndex/pdfDoc.numPages;const leftWidth=3+8*ratio;const rightWidth=3+8*(1-ratio);leftThickness.style.opacity="1";rightThickness.style.opacity="1";leftThickness.style.top=`${minTop}px`;rightThickness.style.top=`${minTop}px`;leftThickness.style.height=`${height}px`;rightThickness.style.height=`${height}px`;leftThickness.style.left=`${minLeft - leftWidth}px`;rightThickness.style.left=`${maxRight}px`;leftThickness.style.width=`${leftWidth}px`;rightThickness.style.width=`${rightWidth}px`}
function centerCover(){if(window.innerWidth<=768)return;const parentEl=document.querySelector(".stf__parent");if(parentEl&&pageFlip){if(pageFlip.getCurrentPageIndex()===0){const width=parentEl.offsetWidth;parentEl.style.marginLeft=`-${width / 6}px`}else{parentEl.style.marginLeft="0px"}}}
function updateBookShadow(){const parentEl=document.querySelector(".stf__parent");if(parentEl&&pageFlip){if(pageFlip.getCurrentPageIndex()>0&&window.innerWidth>768){parentEl.classList.add("active")}else{parentEl.classList.remove("active")}}}
async function renderPage(pageNum){if(cache.has(pageNum))return cache.get(pageNum);const page=await pdfDoc.getPage(pageNum);const viewport=page.getViewport({scale:2*zoomLevel});const canvas=document.createElement("canvas");const ctx=canvas.getContext("2d");canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:ctx,viewport:viewport}).promise;cache.set(pageNum,canvas);return canvas}
async function hydratePage(pageNum){const pageEl=document.querySelector(`[data-page="${pageNum}"]`);if(!pageEl||pageEl.dataset.loaded==="1")return;const loader=document.getElementById("pageLoader");const currentIndex=pageFlip?pageFlip.getCurrentPageIndex()+1:1;if(pageNum===currentIndex&&loader){loader.style.display="flex";const loaderText=document.getElementById("loaderText");if(loaderText)loaderText.innerText=`Loading page ${pageNum}...`}
const progressBar=document.getElementById("loaderProgress");if(progressBar)progressBar.style.width="20%";const canvas=await renderPage(pageNum);if(progressBar)progressBar.style.width="80%";pageEl.innerHTML="";pageEl.appendChild(canvas);pageEl.dataset.loaded="1";if(progressBar)progressBar.style.width="100%";if(pageNum===currentIndex&&loader){setTimeout(()=>{loader.style.display="none";if(progressBar)progressBar.style.width="0%"},200)}}
async function preloadAround(pageNum){const start=Math.max(1,pageNum-2);const end=Math.min(pdfDoc.numPages,pageNum+2);for(let i=start;i<=end;i++){hydratePage(i)}
cleanup(pageNum)}
function cleanup(currentPage){for(const[pageNum]of cache){if(pageNum<currentPage-5||pageNum>currentPage+5){cache.delete(pageNum);const pageEl=document.querySelector(`[data-page="${pageNum}"]`);if(pageEl){pageEl.dataset.loaded="0";pageEl.innerHTML=`
                    <div class="page-loader">
                        <div class="spinner"></div>
                    </div>
                `}}}}
async function buildTOC(){const container=document.getElementById("tocSidebar");if(!container)return;container.innerHTML="";const spreads=[{leftPage:16,rightPage:17,page:17},{leftPage:42,rightPage:43,page:43},{leftPage:86,rightPage:87,page:87},{leftPage:166,rightPage:167,page:167},{leftPage:348,rightPage:349,page:349},{leftPage:364,rightPage:365,page:365},{leftPage:374,rightPage:375,page:375},{leftPage:688,rightPage:689,page:689},{leftPage:690,rightPage:691,page:691},{leftPage:723,rightPage:724,page:724}];for(const item of spreads){const itemEl=document.createElement("div");itemEl.className="toc-spread-item";const wrapper=document.createElement("div");wrapper.className="toc-pages-wrapper";if(item.leftPage&&item.leftPage>0){const canvasLeft=await renderPage(item.leftPage);const c=document.createElement("canvas");c.width=canvasLeft.width;c.height=canvasLeft.height;c.getContext("2d").drawImage(canvasLeft,0,0);wrapper.appendChild(c)}
if(item.rightPage&&item.rightPage<=pdfDoc.numPages){const canvasRight=await renderPage(item.rightPage);const c=document.createElement("canvas");c.width=canvasRight.width;c.height=canvasRight.height;c.getContext("2d").drawImage(canvasRight,0,0);wrapper.appendChild(c)}
const numbersEl=document.createElement("div");numbersEl.className="toc-page-numbers";numbersEl.innerHTML=`
            <span>${item.leftPage || ""}</span>
            <span>${item.rightPage || ""}</span>
        `;itemEl.appendChild(wrapper);itemEl.appendChild(numbersEl);itemEl.onclick=()=>{pageFlip.flip(item.page-1);const overlay=document.getElementById("tocOverlay");if(overlay)overlay.classList.remove("active");};container.appendChild(itemEl)}}
function applyZoom(){const bookEl=document.getElementById("book");if(bookEl){bookEl.style.transform=`scale(${zoomLevel})`}
const zoomVal=document.getElementById("zoomValue");if(zoomVal){zoomVal.innerText=`${Math.round(100 * zoomLevel)}%`}}
async function init(){pdfDoc=await pdfjsLib.getDocument(PDF_URL).promise;await pdfDoc.getOutline();const pagesContainer=document.getElementById("pages-container");for(let i=1;i<=pdfDoc.numPages;i++){const placeholder=createPlaceholder(i);pagesContainer.appendChild(placeholder)}
const isMobile=window.innerWidth<768;pageFlip=new St.PageFlip(document.getElementById("book"),{width:PAGE_WIDTH,height:PAGE_HEIGHT,size:"stretch",flippingTime:400,maxShadowOpacity:0.2,drawShadow:!0,minWidth:isMobile?250:300,maxWidth:2000,minHeight:isMobile?300:400,maxHeight:3000,showCover:!isMobile,mobileScrollSupport:!0,clickEventForward:!0,usePortrait:!0,useMouseEvents:!0});pageFlip.loadFromHTML(document.querySelectorAll("#pages-container .page"));pageFlip.on("changeState",(e)=>{if(e.data==="read"){thicknessLocked=!1;requestAnimationFrame(()=>{requestAnimationFrame(()=>{updateThickness()})})}});window.addEventListener("resize",updateThickness);setTimeout(updateThickness,500);updateBookShadow();buildTOC();const tocFirst=document.getElementById("tocFirstPage");if(tocFirst){tocFirst.addEventListener("click",()=>{pageFlip.flip(0);document.getElementById("tocOverlay").classList.remove("active")})}
const tocLast=document.getElementById("tocLastPage");if(tocLast){tocLast.addEventListener("click",()=>{pageFlip.flip(pdfDoc.numPages-1);document.getElementById("tocOverlay").classList.remove("active")})}
setTimeout(()=>{positionButtons();centerCover();document.getElementById("book").style.opacity="1"},300);pageFlip.on("flip",()=>{centerCover()});await preloadAround(1);const mobileInput=document.getElementById("mobilePageInput");if(mobileInput)mobileInput.value=1;const mobileTotal=document.getElementById("mobileTotalPages");if(mobileTotal)mobileTotal.innerText=`/ ${pdfDoc.numPages}`;const desktopTotal=document.getElementById("totalPages");if(desktopTotal)desktopTotal.innerText=`/ ${pdfDoc.numPages}`;pageFlip.on("flip",async(e)=>{const currentPageNum=e.data+1;const mainInput=document.getElementById("pageInput");if(mainInput)mainInput.value=currentPageNum;if(mobileInput)mobileInput.value=currentPageNum;updateBookShadow();preloadAround(currentPageNum)});setTimeout(()=>{const loader=document.getElementById("initialLoader");if(loader)loader.classList.add("hide");document.body.style.overflow=""},300)}
window.addEventListener("resize",()=>{positionButtons();if(pageFlip)pageFlip.update();});const pageInput=document.getElementById("pageInput");if(pageInput){pageInput.addEventListener("keydown",function(e){if(e.key==="Enter"){let p=parseInt(this.value);if(!isNaN(p)){p=Math.max(1,Math.min(p,pdfDoc.numPages));pageFlip.flip(p-1)}}})}
const mobilePageInput=document.getElementById("mobilePageInput");if(mobilePageInput){mobilePageInput.addEventListener("keydown",function(e){if(e.key==="Enter"){let p=parseInt(this.value);if(!isNaN(p)){p=Math.max(1,Math.min(p,pdfDoc.numPages));pageFlip.flip(p-1)}}})}
const prevBtn=document.getElementById("prev");if(prevBtn)prevBtn.onclick=()=>pageFlip&&pageFlip.flipPrev();const nextBtn=document.getElementById("next");if(nextBtn)nextBtn.onclick=()=>pageFlip&&pageFlip.flipNext();const pagePrevBtn=document.getElementById("pagePrev");if(pagePrevBtn)pagePrevBtn.onclick=()=>pageFlip&&pageFlip.flipPrev();const pageNextBtn=document.getElementById("pageNext");if(pageNextBtn)pageNextBtn.onclick=()=>pageFlip&&pageFlip.flipNext();const zoomInBtn=document.getElementById("zoomIn");if(zoomInBtn){zoomInBtn.onclick=()=>{zoomLevel=Math.min(3,zoomLevel+0.1);applyZoom()}}
const zoomOutBtn=document.getElementById("zoomOut");if(zoomOutBtn){zoomOutBtn.onclick=()=>{zoomLevel=Math.max(0.5,zoomLevel-0.1);applyZoom()}}
const fullscreenBtn=document.getElementById("fullscreenBtn");if(fullscreenBtn){fullscreenBtn.onclick=async()=>{const viewer=document.querySelector(".viewer");if(document.fullscreenElement){await document.exitFullscreen()}else if(viewer){await viewer.requestFullscreen()}}}
document.addEventListener("fullscreenchange",()=>{if(fullscreenBtn){fullscreenBtn.innerHTML=document.fullscreenElement?"⮌":"⛶"}
setTimeout(()=>{if(pageFlip){pageFlip.update();positionButtons()}},100)});const downloadBtn=document.getElementById("downloadBtn");if(downloadBtn){downloadBtn.onclick=()=>{const fileName=PDF_URL.split("/").pop();const a=document.createElement("a");a.href=PDF_URL;a.download=fileName;a.click()}}
const mPrev=document.getElementById("mobilePrev");if(mPrev)mPrev.onclick=()=>prevBtn&&prevBtn.click();const mNext=document.getElementById("mobileNext");if(mNext)mNext.onclick=()=>nextBtn&&nextBtn.click();const mZoomIn=document.getElementById("mobileZoomIn");if(mZoomIn)mZoomIn.onclick=()=>zoomInBtn&&zoomInBtn.click();const mZoomOut=document.getElementById("mobileZoomOut");if(mZoomOut)mZoomOut.onclick=()=>zoomOutBtn&&zoomOutBtn.click();const mFullscreen=document.getElementById("mobileFullscreen");if(mFullscreen)mFullscreen.onclick=()=>fullscreenBtn&&fullscreenBtn.click();const mDownload=document.getElementById("mobileDownload");if(mDownload)mDownload.onclick=()=>downloadBtn&&downloadBtn.click();const tocBtn=document.getElementById("tocButton");if(tocBtn){tocBtn.onclick=()=>{document.getElementById("tocOverlay").classList.add("active")}}
const closeToc=document.getElementById("closeToc");if(closeToc){closeToc.onclick=()=>{document.getElementById("tocOverlay").classList.remove("active")}}
const tocOverlay=document.getElementById("tocOverlay");if(tocOverlay){tocOverlay.addEventListener("click",function(e){if(e.target===this)this.classList.remove("active");})}
const mobileToc=document.getElementById("mobileToc");if(mobileToc){mobileToc.onclick=()=>{document.getElementById("tocOverlay").classList.add("active")}}
document.querySelectorAll(".lang-btn").forEach((btn)=>{btn.addEventListener("click",function(){const lang=this.dataset.lang;localStorage.setItem("language",lang);const url=new URL(window.location);url.searchParams.set("lang",lang);window.location.href=url.toString()})});const firstPageBtn=document.getElementById("firstPageBtn");if(firstPageBtn){firstPageBtn.addEventListener("click",()=>{pageFlip.flip(0)})}
const lastPageBtn=document.getElementById("lastPageBtn");if(lastPageBtn){lastPageBtn.addEventListener("click",()=>{pageFlip.flip(pdfDoc.numPages-1)})}
